def can_remove(a):
    """Check if we can remove all stones without any swap."""
    carry = 0
    for stones in a:
        carry = stones - carry
        if carry < 0:
            return False
    return carry == 0

def can_remove_with_swap(a):
    """Check if we can remove all stones, possibly with one adjacent swap."""
    if can_remove(a):
        return True

    n = len(a)
    # Try swapping each adjacent pair
    for i in range(n - 1):
        # Create new array with a swap at position i
        new_a = a[:i] + [a[i+1]] + [a[i]] + a[i+2:]
        if can_remove(new_a):
            return True

    return False

def solution(input_str):
    """
    Process the input string and return results for each test case.
    Each test case checks if we can remove all stones with at most one adjacent swap.
    """
    import sys
    from io import StringIO

    data = input_str.strip().split('\n')
    idx = 0

    if not data or not data[0].strip():
        return ""

    t = int(data[idx])
    idx += 1

    result = []

    for _ in range(t):
        if idx >= len(data):
            break
        n = int(data[idx])
        idx += 1

        if idx >= len(data):
            break

        a = list(map(int, data[idx].split()))
        idx += 1

        if can_remove_with_swap(a):
            result.append("YES")
        else:
            result.append("NO")

    return '\n'.join(result)
