def solution(input_str):
    lines = input_str.strip().split()
    if not lines:
        return '-1\n'

    n = int(lines[0])
    a = [int(lines[i]) for i in range(1, n+1)]

    total_sum = sum(a)

    # If total sum <= 1, no divisor > 1 exists
    if total_sum <= 1:
        return '-1\n'

    def compute_cost(a_arr, k):
        cost = 0
        cumulative_sum = 0
        for x in a_arr:
            cumulative_sum += x
            cost += abs(cumulative_sum % k)
        return cost

    best = float('inf')

    # Check all divisors of total_sum (up to sqrt(total_sum))
    i = 2
    while i * i <= total_sum:
        if total_sum % i == 0:
            # Check divisor i
            cost = compute_cost(a, i)
            best = min(best, cost)

            # Check divisor total_sum // i
            if i * i != total_sum:
                j = total_sum // i
                cost = compute_cost(a, j)
                best = min(best, cost)
        i += 1

    if best == float('inf'):
        return '-1\n'
    else:
        return str(best) + '\n'
