def compute_combinations(n, k, mod):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if n - k < k:
        k = n - k
    if k == 0:
        return 1

    result = 1
    for i in range(k):
        result = result * (n - i) % mod
        result = result * pow(i + 1, mod - 2, mod) % mod
