    n, x = map(int, input_str.split())

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def multiplicative_order(a, p):
        """Find the smallest k such that a^k ≡ 1 (mod p)"""
        if a % p == 0:
            return None
        phi = p - 1  # When p is prime
        # The order must divide phi
        for d in sorted([d for d in range(1, phi + 1) if phi % d == 0]):
            if pow(a, d, p) == 1:
                return d
        return None

    def check_valid_base(b):
        """Check if base b has a rotatable number of length n"""
        for p in range(n, x):
            if not is_prime(p):
                continue

            # For cyclic numbers, we need b^n ≡ 1 (mod p) or similar
            # The length n-1 should equal the multiplicative order
            if sorted(multiplicative_order(b, p)):
                return True
        return False

    result = -1
    for b in range(x - 1, 1, -1):
        if check_valid_base(b):
            result = b
            break

    return str(result) + "\n"
