def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())

    # If graph is already a tree, no output
    if m <= n - 1:
        return ""

    # Parse edges: (original_index, u, v, weight)
    edges = []
    for i in range(m):
        parts = lines[i+1].split()
        u, v, e = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((i, u - 1, v - 1, e))  # Convert to 0-indexed

    # Sort by weight for Kruskal's
    edges.sort(key=lambda x: x[3])

    # Disjoint Set Union
    parent = list(range(n))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    # Build MST
    mst_indices = set()
    adj = [[] for _ in range(n)]
    for orig_idx, u, v, w in edges:
        if union(u, v):
            mst_indices.add(orig_idx)
            adj[u].append((v, w))
            adj[v].append((u, w))

    # Binary lifting: up[u][k] = 2^k-th ancestor, maxw[u][k] = max edge to that ancestor
    LOG = 20
    up = [[-1] * LOG for _ in range(n)]
    maxw = [[0] * LOG for _ in range(n)]

    # BFS to compute depths and immediate parents (2^0 ancestors)
    depth = [0] * n
    queue = [0]
    visited = [False] * n
    visited[0] = True

    while queue:
        u = queue.pop(0)
        for v, w in adj[u]:
            if not visited[v]:
                visited[v] = True
                depth[v] = depth[u] + 1
                up[v][0] = u
                maxw[v][0] = w
                queue.append(v)

    # Compute up[u][k] and maxw[u][k] for k >= 1
    for k in range(1, LOG):
        for u in range(n):
            if up[u][k-1] != -1:
                p = up[u][k-1]
                up[u][k] = up[p][k-1]
                maxw[u][k] = max(maxw[u][k-1], maxw[p][k-1])
            else:
                up[u][k] = -1
                maxw[u][k] = maxw[u][k-1]

    def get_path_max(u, v):
        """Get maximum edge on path between u and v in the tree."""
        if u == v:
            return 0

        # Lift u to same depth as v
        res = 0
        if depth[u] < depth[v]:
            u, v = v, u

        diff = depth[u] - depth[v]
        for k in range(LOG):
            if (diff >> k) & 1:
                res = max(res, maxw[u][k])
                u = up[u][k]

        if u == v:
            return res

        # Lift both until they're just below LCA
        for k in range(LOG - 1, -1, -1):
            if up[u][k] != up[v][k]:
                res = max(res, maxw[u][k])
                res = max(res, maxw[v][k])
                u = up[u][k]
                v = up[v][k]

        # Both are now children of LCA
        res = max(res, maxw[u][0])
        res = max(res, maxw[v][0])

        return res

    # For each non-MST edge, compute max edge on path between its endpoints
    results = []
    for orig_idx, u, v, w in sorted(edges, key=lambda x: x[0]):  # Restore original order
        if orig_idx not in mst_indices:
            results.append(str(get_path_max(u, v)))

    return '\n'.join(results)
