from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))

    adj = [[] for _ in range(n)]
    for i in range(m):
        parts = lines[3 + i].split()
        p, q = int(parts[0]) - 1, int(parts[1]) - 1
        adj[p].append(q)
        adj[q].append(p)

    source = n
    sink = n + 1
    total_nodes = sink + 1

    class Dinic:
        def __init__(self, n):
            self.n = n
            self.graph = [[] for _ in range(n)]

        def add_edge(self, u, v, capacity):
            self.graph[u].append([v, capacity, len(self.graph[v]), 0])
            self.graph[v].append([u, 0, len(self.graph[u]) - 1, 0])

        def bfs(self, s, t):
            level = [-1] * self.n
            level[s] = 0
            q = deque([s])
            while q:
                u = q.popleft()
                for v, cap, rev_idx, flow in self.graph[u]:
                    if cap - flow > 0 and level[v] < 0:
                        level[v] = level[u] + 1
                        q.append(v)
            return level[t] != -1

        def dfs(self, u, t, flow, ptr, level):
            if u == t or flow == 0:
                return flow
            total_pushed = 0
            for i in range(ptr[u], len(self.graph[u])):
                ptr[u] = i
                v, cap, rev_idx, f = self.graph[u][i]
                if level[v] == level[u] + 1 and cap - f > 0:
                    pushed = self.dfs(v, t, min(flow, cap - f), ptr, level)
                    if pushed > 0:
                        self.graph[u][i][3] += pushed
                        self.graph[v][rev_idx][3] -= pushed
                        total_pushed += pushed
                        if total_pushed == flow:
                            break
            return total_pushed

        def max_flow(self, s, t):
            total = 0
            while self.bfs(s, t):
                ptr = [0] * self.n
                while True:
                    pushed = self.dfs(s, t, float('inf'), ptr, [])
                    if pushed == 0:
                        break
                    total += pushed
            return total

    dinic = Dinic(total_nodes)

    for i in range(n):
        dinic.add_edge(source, i, a[i])

    for i in range(n):
        dinic.add_edge(i, sink, b[i])

    for u in range(n):
        for v in adj[u]:
            if u < v:
                dinic.add_edge(u, v, float('inf'))
                dinic.add_edge(v, u, float('inf'))

    max_flow_val = dinic.max_flow(source, sink)
    total_initial = sum(a)

    if max_flow_val == total_initial:
        result = ['YES']
        for i in range(n):
            row = []
            for j in range(n):
                if i == j:
                    row.append('0')
                elif j in adj[i]:
                    row.append(str(dinic.graph[i][j][3]))
                else:
                    row.append('0')
            result.append(' '.join(row))
        return '\n'.join(result)
    else:
        return 'NO'
