    e = list(map(int, lines[2].split()))

    # Compute overall GCD
    overall_gcd = 0
    for x in a:
        overall_gcd = gcd(overall_gcd, x)

    if overall_gcd == 1:
        return "0"

    # Factorize G into prime factors
    temp = overall_gcd
    primes = []
    d = 2
    while d * d <= temp:
        if temp % d == 0:
            primes.append(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        primes.append(temp)

    m = len(primes)
    full_mask = (1 << m) - 1

    # If any prime factor exceeds k, impossible
    for p in primes:
        if p > k:
            return "-1"

    # For each prime, check if any judge can eliminate it
    can_eliminate = [False] * m
    for i in range(n):
        for j, p in enumerate(primes):
            if a[i] % p == 0 and p <= k:
                can_eliminate[j] = True

    if not all(can_eliminate):
        return "-1"

    # Group teachers by their elimination pattern (bitmask)
    mask_to_teachers = defaultdict(list)
    for i in range(n):
        mask = 0
        for j, p in enumerate(primes):
