import sys
sys.setrecursionlimit(200000)

def solution(m):
    if not m:
        return '\n0\n\n'

    n = len(m)

    # Find runs of '#'
    runs = []
    i = 0
    while i < n:
        if m[i] == '#':
            start = i
            while i < n and m[i] == '#':
                i += 1
            runs.append((start, i - 1, i - start))
        else:
            i += 1

    # No '#' means empty profile
    if not runs:
        return '\n0\n\n'

    # All '#' means single group of size n
    if len(runs) == 1 and runs[0][0] == 0 and runs[0][1] == n - 1:
        return f'\n1\n{n}\n'

    first_run_start, last_run_end = runs[0][0], runs[-1][1]

    def generate_partitions(total, num_groups, min_size):
        if num_groups == 0:
            return [[]] if total == 0 else []
        if total < min_size * num_groups:
            return []
        result = []
        for size in range(min_size, min(total - (num_groups - 1) * min_size, total) + 1):
            for other in generate_partitions(total - size, num_groups - 1, min_size):
                if len(other) < num_groups - 1:
                    continue
                result.append([size] + other)
        return result

    def compute_always_filled(profile):
        """
        For a profile [g1, g2, ..., gk], compute positions that are
        ALWAYS filled across all valid placements.
        """
        always = set()
        k = len(profile)

        # Total filled cells = sum(group sizes)
        total_filled = sum(profile)
        min_gaps = k - 1
        min_span = total_filled + min_gaps

        if min_span > n:
            return set()

        # Find range where groups can start
        # First group can start from 0 to n - total_filled - (k-1)
        first_start_max = n - min_span

        # Compute for each cell whether it's always filled
        for start_first in range(first_start_max + 1):
            # Compute a specific valid placement starting at first group position
            placements = [start_first]
            current = start_first
            for sz in profile:
                placements.append(current + sz)
                current = placements[-1] + 1

            # Normalize all placements to be relative to this start
            actual_placements = []
            valid_count = 0
            for g_start in range(first_start_max + 1):
                possible = True
                last_pos = -100  # Track end position
                for i, sz in enumerate(profile):
                    pos = g_start + sum(profile[:i]) + i
                    if pos > n - sz:
                        possible = False
                        break
                    last_pos = pos + sz - 1
                    actual_placements.append(set(range(pos, pos + sz)))
                if possible:
                    valid_count += 1

            if valid_count == 0:
                continue

            # Find cells filled in ALL valid placements
            if len(actual_placements) > 0:
                intersection = actual_placements[0]
                for p in actual_placements[1:]:
                    intersection = intersection & p
                always.update(intersection)

        return list(always)

    def profile_matches_mask(profile):
        always_filled = compute_always_filled(profile)

        for i in range(n):
            if m[i] == '#' and i not in always_filled:
                return False
            if m[i] == '_' and i in always_filled:
                return False

        # All '#' in mask must be covered
        for start, end, length in runs:
            is_covered = True
            for i in range(end - start + 1):
                if (start + i) not in always_filled:
                    is_covered = False
                    break
            if not is_covered:
                return False

        return True

    # Try different partition counts
    for num_groups in range(1, min(len(runs) + 2, 50)):
        # Partition total cells across groups
        for total_cells in range(max(runs[i][2] for i in range(len(runs))), n - (num_groups - 1) + 1):
