    # Each perfect set is a vector subspace over GF(2)

    # Pattern from analysis:
    # The count depends on whether k = 2^m - 1 or not
    # If k = 2^m - 1, answer = 2^m * 2 - 1 = 2^(m+1) - 1
    # Otherwise interpolate based on k mod

    n = k.bit_length()

    # Direct computation based on pattern
    # For k, compute iteratively
    f = {0: 1}

    def compute_f(n):
        if n in f:
            return f[n]

        prev = compute_f(n - 1)

        # The increase follows binary pattern
        # v2(n) = count of trailing zeros + 1
        increase = 1 << (n & -n).bit_length() - 2 if n > 0 else 1

        # Simplified: at 2^m - 1, jump follows power pattern
        if (n + 1) & n == 0:  # n is 2^m - 1
            increase = 1 << n.bit_length()
        else:
            increase = 1

        f[n] = (prev + increase) % MOD
        return f[n]

    return str(compute_f(k)) + "\n"
